/**
 * @summary Request a presigned upload URL for a validated image
 */
export const requestImageUploadUrlBodyNameMax = 180;

export const requestImageUploadUrlBodySizeMax = 10485760;



export const RequestImageUploadUrlBody = zod.object({
  "name": zod.string().min(1).max(requestImageUploadUrlBodyNameMax),
  "size": zod.number().int().min(1).max(requestImageUploadUrlBodySizeMax),
  "contentType": zod.enum(['image/jpeg', 'image/png', 'image/webp'])
})

export const RequestImageUploadUrlResponse = zod.object({
  "uploadUrl": zod.string().url(),
  "objectPath": zod.string()
})


/**
 * @summary Serve an uploaded image
 */
export const GetStoredImageParams = zod.object({
  "objectPath": zod.coerce.string()
})

export const GetStoredImageResponse = zod.unknown()


